import type { AssetsBundle } from 'pixi.js';

/** Atlases that make up the "game" bundle. Generated by `npm run assets` into `public/assets/game`. */
export const GAME_ATLASES = ['ships', 'tiles', 'terrain', 'ui'] as const;
export type GameAtlas = (typeof GAME_ATLASES)[number];

/** Plain textures of the bundle (not atlases): the sea, which is drawn as a repeating, moving pattern. */
export const GAME_TEXTURES = ['water'] as const;
export type GameTextureName = (typeof GAME_TEXTURES)[number];

export const GAME_BUNDLE = 'game';

/** Texture resolution to request. Ships only exist at 1×; tiles, terrain and UI have 1× and 2× variants. */
export type AtlasResolution = 1 | 2;

export function pickAtlasResolution(devicePixelRatio: number): AtlasResolution {
  return devicePixelRatio >= 1.5 ? 2 : 1;
}

export function atlasFile(atlas: GameAtlas, resolution: AtlasResolution): string {
  return atlas === 'ships' ? 'ships.json' : `${atlas}@${resolution}x.json`;
}

/** Builds the PixiJS bundle descriptor. `baseUrl` must end with a slash (e.g. `import.meta.env.BASE_URL`). */
export function createGameBundle(baseUrl: string, resolution: AtlasResolution): AssetsBundle {
  return {
    name: GAME_BUNDLE,
    assets: [
      ...GAME_ATLASES.map((atlas) => ({ alias: atlas, src: `${baseUrl}assets/game/${atlasFile(atlas, resolution)}` })),
      ...GAME_TEXTURES.map((texture) => ({ alias: texture, src: `${baseUrl}assets/game/${texture}.png` })),
    ],
  };
}
